-- Data Center batch, Oct 7 2026: formulas for 27 planned markers that the deployed workbench-derived
-- engine can already compute from live inputs. Rows are staged live in the formula registry so the canary
-- can call them; data_center_provider_coverage stays planned until the canary passes and an activation
-- migration cites it.

on conflict(marker_id) do update set engine_version=excluded.engine_version,formula=excluded.formula,dependencies=excluded.dependencies,confidence=excluded.confidence,status=excluded.status,explanation=excluded.explanation,operation=excluded.operation,config=excluded.config,updated_at=now();

-- Seven older score ids that repeat a live score keep their ids and read the live value or the same
-- town inputs. Added/omitted assessment risk waits for the added/omitted history pull.
on conflict(marker_id) do update set engine_version=excluded.engine_version,formula=excluded.formula,dependencies=excluded.dependencies,confidence=excluded.confidence,status=excluded.status,explanation=excluded.explanation,operation=excluded.operation,config=excluded.config,updated_at=now();

-- Allow the new batch canary, the municipal context canary (municipal_context_oct7_v1), and catalog_njdep_layers_v2 (written for the 5 NJDEP layer markers that
-- returned no value in v1), to be dispatched once provider-release-canary v046 is deployed.
create or replace function public.dispatch_provider_release_canary(p_scenario text)
returns bigint language plpgsql set search_path to 'public','extensions' as $$
declare v_raw text := encode(gen_random_bytes(48), 'hex'); v_email text := 'watchdog-provider-canary-' || substr(v_raw,1,10) || '@example.com'; v_request_id bigint;
begin
 if p_scenario not in ('zoning_v31','designation_stack_v15','csrr_v1','csrr_controls_v2','csrr_semantics_v3','geology_intersections_v1','model_bounds_v1','uniformity_history_v1','uniformity_history_v2','uniformity_history_v3','modiv_longitudinal_v1','modiv_longitudinal_partial_scan_v1','modiv_longitudinal_missing_year_v1','community_assets_access_v1','zoning_contact_status_v1','pilot_observed_v1','v036_sources_v1','modiv_record_change_v1','affordable_housing_v037','development_trends_v038','ufb_v039','ufb_longitudinal_v040','njw294_deterministic_v1','catalog_njdep_layers_v1','catalog_njdep_layers_v2','data_center_batch_oct7_v1','municipal_context_oct7_v1') then raise exception 'Unsupported release canary scenario'; end if;
 select net.http_post(url := 'https://uvkvaxljhhngydvlrzom.supabase.co/functions/v1/provider-release-canary',headers := jsonb_build_object('Content-Type','application/json'),body := jsonb_build_object('token',v_raw,'scenario',p_scenario),timeout_milliseconds := 30000) into v_request_id; return v_request_id;
end; $$;
revoke all on function public.dispatch_provider_release_canary(text) from public, anon, authenticated;
grant execute on function public.dispatch_provider_release_canary(text) to service_role;
